func unwrapAvroUnion(v interface{}) interface{} {
	if v == nil {
		return nil
	}
	if m, ok := v.(map[string]interface{}); ok && len(m) == 1 {
		for k, val := range m {
			if strings.HasPrefix(k, "$") {
				return v
			}
			return val
		}
	}
	return v
}

